    MODEL="$VOLC_CODING_DEFAULT_MODEL"
    VOLC_MODELS=("$VOLC_CODING_DEFAULT_MODEL" "$VOLC_CODING_FALLBACK_MODEL")
    ENABLED_MODELS="$PROVIDER/$VOLC_CODING_DEFAULT_MODEL,$PROVIDER/$VOLC_CODING_FALLBACK_MODEL"
    PI_USER_DIR="$PI_VOLC_CODING_USER_DIR"
    PI_AGENT_DIR="$PI_VOLC_CODING_AGENT_DIR"
    VOLC_PROFILE_TYPE="coding-plan"
    VOLC_PROVIDER="$PROVIDER"
