    PROVIDER_READY=0
    PACKAGE_SOURCES=("$PORTABLE_WEB_PACKAGE" "$MCP_PACKAGE")
    PACKAGE_NAMES=("$PORTABLE_WEB_PACKAGE_NAME" "$MCP_PACKAGE_NAME")
else
    ENABLED_MODELS="$CODEX_MODELS,$CLAUDE_MODELS,$KIMI_MODELS"
    PI_USER_DIR="$PI_COMMON_USER_DIR"
