    PACKAGE_SOURCE="$KIMI_PROVIDER_PACKAGE"
    PACKAGE_SOURCES=("$KIMI_PROVIDER_PACKAGE" "$CLAUDE_AUTH_PACKAGE" "$PORTABLE_WEB_PACKAGE")
